"""Exact noiseless Steane gauge-byproduct acceptance without feedforward."""
import numpy as np,json
from pathlib import Path
# Eight codewords generated by the three X stabilizers.
G=[85,102,120];code={0}
for g in G:code|={v^g for v in list(code)}
psi=np.zeros(128,complex)
for v in code:psi[v]=1/4;psi[v^127]=np.exp(1j*np.pi/4)/4
# Logical Pauli representatives are transversal X and Z on all seven wires.
paulis={}
for x in (0,1):
 for z in (0,1):
  vec=np.zeros(128,complex)
  for b,a in enumerate(psi):vec[b^(127 if x else 0)] += a*(-1 if z and b.bit_count()%2 else 1)
  paulis[('I','Z','X','XZ')[2*x+z]]=vec
# W=T^dagger X T acts |0> -> e^{-i pi/4}|1>, |1> -> e^{i pi/4}|0>.
rows=[]
for mask in range(128):
 out=np.zeros(128,complex)
 for b,a in enumerate(psi):
  phase=np.exp(-1j*np.pi/4*((mask.bit_count())-2*(mask&b).bit_count()))
  out[b^mask]+=a*phase
 overlap=abs(np.vdot(psi,out))**2
 # Project onto the Steane codespace without applying a record-dependent frame.
 projected=out.copy()
 for g in G:
  projected=np.array([(projected[i]+projected[i^g])/2 for i in range(128)])
  projected=np.array([v*(0 if (i&g).bit_count()%2 else 1) for i,v in enumerate(projected)])
 code_accept=float(np.vdot(projected,projected).real)
 conditional_fidelity=float(overlap/code_accept) if code_accept>1e-12 else None
 frame_overlaps={k:float(abs(np.vdot(vec,projected))**2) for k,vec in paulis.items()}
 frame_max=max(frame_overlaps.values());frame_best=max(frame_overlaps,key=frame_overlaps.get)
 raw_in_code=all(abs(float(x)-1)<1e-9 for x in [sum(abs(v)**2*(-1 if (b&g).bit_count()%2 else 1)for b,v in enumerate(out))for g in G]+[sum(np.conj(out[b])*out[b^g]for b in range(128)).real for g in G])
 # Raw stabilizer expectations before the decoder.
 z=[sum(abs(v)**2*(-1 if (b&g).bit_count()%2 else 1)for b,v in enumerate(out)) for g in G]
 xx=[sum(np.conj(out[b])*out[b^g]for b in range(128)).real for g in G]
 rows.append({'mask':mask,'overlap':round(overlap,12),'code_accept':code_accept,'conditional_fidelity':conditional_fidelity,'pauli_frame_overlaps':frame_overlaps,'best_logical_pauli':frame_best,'best_frame_conditional_fidelity':float(frame_max/code_accept) if code_accept>1e-12 else None,'raw_in_codespace':bool(raw_in_code),'Z':[float(x)for x in z],'X':[float(x)for x in xx],'raw_good':bool(abs(overlap-1)<1e-9 and all(abs(x-1)<1e-9 for x in z+xx))})
# Q' and its complement represent the same gauge boundary. Each of 64
# equiprobable edge records labels exactly one unordered complementary pair.
pairs=[(a,a^127)for a in range(64)];good=[p for p in pairs if rows[p[0]]['raw_good'] and rows[p[1]]['raw_good']]
report={'source':'Mathematical gauge-frame analysis on exact Steane T state; assumes every gauge measurement recorded, no physical corrections, and product-W byproducts per Hetenyi et al.','good_pairs':good,'count_good_pairs':len(good),'total_pairs':len(pairs),'conditional_acceptance_given_logical_plus':len(good)/len(pairs),'unconditional_acceptance_with_random_logical_sign':len(good)/128,'acceptance_after_perfect_codespace_projection':sum(rows[a]['code_accept'] for a in range(64))/64,'mean_conditional_fidelity_after_projection':sum(rows[a]['overlap'] for a in range(64))/sum(rows[a]['code_accept'] for a in range(64)),'raw_code_class_count':sum(rows[a]['raw_in_codespace'] for a in range(64)),
 'raw_code_and_pauli_correctable_class_count':sum(rows[a]['raw_in_codespace'] and max(rows[a]['pauli_frame_overlaps'].values())>1-1e-9 for a in range(64)),
 'postprojection_pauli_correctable_class_count':sum(rows[a]['code_accept']>1e-12 and rows[a]['best_frame_conditional_fidelity']>1-1e-9 for a in range(64)),
 'postprojection_nonzero_class_count':sum(rows[a]['code_accept']>1e-12 for a in range(64)),
 'postprojection_pauli_corrected_target_weight':sum(max(rows[a]['pauli_frame_overlaps'].values()) for a in range(64))/64,
 'rows':rows}
Path(__file__).with_suffix('.json').write_text(json.dumps(report,indent=2)+'\n');print({k:v for k,v in report.items() if k!='rows'})
